namespace EzCrosshair
{
    // The crosshairs, drawn by art/make.py at 8 times their size, kept here so the mod is a single dll.
    internal static class Images
    {
        internal const int Density = 8;

        public static string Get(string name)
        {
            switch (name)
            {
                case "brackets": return "";
                case "chunky plus": return "";
                case "circle": return "";
                case "cross": return "";
                case "dark diamond": return "";
                case "diamond": return "";
                case "dot": return "";
                case "outlined plus": return "";
                case "pinhole": return "";
                case "plus": return "";
                case "square": return "iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMklEQVR4Xu3QQQ0AAAgDMcC/55Fggk/PwJZ2ktRj87h9OUCAAAECBAgQIECAAAECBAgsTYgEPCyxfK8AAAAASUVORK5CYII=";
                case "star": return "";
                default: return null;
            }
        }
    }
}
